// @ts-check
// Reads what a publishing step needs from an audio or image file's own bytes:
// duration, bitrate, sample rate, channels and constant-vs-variable bitrate
// for MP3 / M4A / M4B / WAV, and pixel size and colour model for PNG / JPEG.
//
// Pure: takes a Uint8Array, does no I/O, so the CLI (which reads the file from
// disk) and the browser page (which reads a dropped File) get the same answer.
// No decoding of audio samples except for 16-bit PCM WAV, where loudness can be
// measured directly (see measureWavLoudness).

const MP3_BITRATES = {
  v1: [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320],
  v2: [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160],
};
const MP3_SAMPLE_RATES = { 3: [44100, 48000, 32000], 2: [22050, 24000, 16000], 0: [11025, 12000, 8000] };

/** @param {Uint8Array} b @param {number} o */
const u32 = (b, o) => ((b[o] << 24) >>> 0) + (b[o + 1] << 16) + (b[o + 2] << 8) + b[o + 3];
/** @param {Uint8Array} b @param {number} o */
const u16 = (b, o) => (b[o] << 8) + b[o + 1];
/** @param {Uint8Array} b @param {number} o */
const le32 = (b, o) => b[o] + (b[o + 1] << 8) + (b[o + 2] << 16) + ((b[o + 3] << 24) >>> 0);
/** @param {Uint8Array} b @param {number} o */
const le16 = (b, o) => b[o] + (b[o + 1] << 8);
/** @param {Uint8Array} b @param {number} o @param {number} n */
const ascii = (b, o, n) => String.fromCharCode(...b.subarray(o, o + n));

/**
 * Guesses the container from magic bytes.
 * @param {Uint8Array} b
 * @returns {'mp3'|'mp4'|'wav'|'png'|'jpeg'|'unknown'}
 */
export function sniff(b) {
  if (b.length >= 8 && b[0] === 0x89 && ascii(b, 1, 3) === 'PNG') return 'png';
  if (b.length >= 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'jpeg';
  if (b.length >= 12 && ascii(b, 0, 4) === 'RIFF' && ascii(b, 8, 4) === 'WAVE') return 'wav';
  if (b.length >= 12 && ascii(b, 4, 4) === 'ftyp') return 'mp4';
  if (b.length >= 3 && ascii(b, 0, 3) === 'ID3') return 'mp3';
  if (b.length >= 2 && b[0] === 0xff && (b[1] & 0xe0) === 0xe0) return 'mp3';
  return 'unknown';
}

/**
 * Parses one MPEG audio frame header at offset o, or returns null.
 * @param {Uint8Array} b @param {number} o
 */
export function mp3FrameHeader(b, o) {
  if (o + 4 > b.length || b[o] !== 0xff || (b[o + 1] & 0xe0) !== 0xe0) return null;
  const version = (b[o + 1] >> 3) & 3; // 3 = MPEG-1, 2 = MPEG-2, 0 = MPEG-2.5
  const layer = (b[o + 1] >> 1) & 3; // 1 = Layer III
  const bitrateIndex = b[o + 2] >> 4;
  const rateIndex = (b[o + 2] >> 2) & 3;
  if (version === 1 || layer !== 1 || bitrateIndex === 0 || bitrateIndex === 15 || rateIndex === 3) return null;
  const kbps = (version === 3 ? MP3_BITRATES.v1 : MP3_BITRATES.v2)[bitrateIndex];
  const sampleRate = MP3_SAMPLE_RATES[version][rateIndex];
  const padding = (b[o + 2] >> 1) & 1;
  const mono = (b[o + 3] >> 6) === 3;
  const samples = version === 3 ? 1152 : 576;
  const length = Math.floor(((samples / 8) * kbps * 1000) / sampleRate) + padding;
  return { version, kbps, sampleRate, channels: mono ? 1 : 2, samples, length };
}

/** @param {Uint8Array} b */
function id3v2Size(b) {
  if (b.length < 10 || ascii(b, 0, 3) !== 'ID3') return 0;
  const size = (b[6] << 21) | (b[7] << 14) | (b[8] << 7) | b[9];
  return 10 + size + (b[5] & 0x10 ? 10 : 0);
}

/**
 * Walks every frame of an MP3, so duration is exact and a file that mixes
 * bitrates is reported as VBR even when it carries no Xing header.
 * @param {Uint8Array} b
 */
export function probeMp3(b) {
  let pos = id3v2Size(b);
  const end = b.length >= 128 && ascii(b, b.length - 128, 3) === 'TAG' ? b.length - 128 : b.length;
  let frames = 0, samples = 0, sampleRate = 0, channels = 0, audioBytes = 0, skipped = 0;
  const bitrates = new Set();
  let first = true;
  while (pos < end - 4) {
    const h = mp3FrameHeader(b, pos);
    if (!h || h.length < 4 || pos + h.length > end + 1) { pos++; skipped++; continue; }
    // A Xing/Info/VBRI frame describes the stream; it carries no audio.
    if (first) {
      first = false;
      const side = h.version === 3 ? (h.channels === 1 ? 17 : 32) : (h.channels === 1 ? 9 : 17);
      const tag = ascii(b, pos + 4 + side, 4);
      if (tag === 'Xing' || tag === 'Info' || ascii(b, pos + 36, 4) === 'VBRI') { pos += h.length; continue; }
    }
    frames++;
    samples += h.samples;
    sampleRate = h.sampleRate;
    channels = Math.max(channels, h.channels);
    bitrates.add(h.kbps);
    audioBytes += h.length;
    pos += h.length;
  }
  if (!frames) return { format: 'mp3', error: 'no MPEG audio frames found' };
  const duration = samples / sampleRate;
  const list = [...bitrates].sort((x, y) => x - y);
  return {
    format: 'mp3',
    mime: 'audio/mpeg',
    duration: round(duration),
    sampleRate,
    channels,
    bitrateKbps: list.length === 1 ? list[0] : Math.round((audioBytes * 8) / duration / 1000),
    cbr: list.length === 1,
    minKbps: list[0],
    maxKbps: list[list.length - 1],
    frames,
    junkBytes: skipped,
  };
}

/**
 * Walks ISO-BMFF boxes (M4A / M4B / MP4) for duration, the AAC sample entry,
 * and whether the file carries chapter markers.
 * @param {Uint8Array} b
 */
export function probeMp4(b) {
  /** @type {{duration?: number, sampleRate?: number, channels?: number, chapters: boolean, mdat: number, brand: string}} */
  const out = { chapters: false, mdat: 0, brand: ascii(b, 8, 4).trim() };
  const containers = new Set(['moov', 'trak', 'mdia', 'minf', 'stbl', 'udta', 'edts', 'tref']);
  /** @param {number} start @param {number} stop */
  const walk = (start, stop) => {
    let p = start;
    while (p + 8 <= stop) {
      let size = u32(b, p);
      const type = ascii(b, p + 4, 4);
      let header = 8;
      if (size === 1) { size = u32(b, p + 8) * 2 ** 32 + u32(b, p + 12); header = 16; }
      else if (size === 0) size = stop - p;
      if (size < header) break;
      const body = p + header;
      if (type === 'mvhd') {
        const v = b[body];
        const ts = v === 1 ? u32(b, body + 20) : u32(b, body + 12);
        const dur = v === 1 ? u32(b, body + 24) * 2 ** 32 + u32(b, body + 28) : u32(b, body + 16);
        if (ts) out.duration = dur / ts;
      } else if (type === 'stsd') {
        walk(body + 8, Math.min(p + size, stop));
      } else if (type === 'mp4a') {
        out.channels = u16(b, body + 16);
        out.sampleRate = u16(b, body + 24);
      } else if (type === 'chpl' || type === 'chap') {
        out.chapters = true;
      } else if (type === 'mdat') {
        out.mdat += size - header;
      } else if (type === 'meta') {
        walk(body + 4, Math.min(p + size, stop));
      } else if (containers.has(type)) {
        walk(body, Math.min(p + size, stop));
      }
      p += size;
    }
  };
  walk(0, b.length);
  if (!out.duration) return { format: 'mp4', error: 'no movie header (moov/mvhd) found' };
  return {
    format: 'mp4',
    mime: out.brand.startsWith('M4B') ? 'audio/x-m4b' : 'audio/mp4',
    brand: out.brand,
    duration: round(out.duration),
    sampleRate: out.sampleRate ?? null,
    channels: out.channels ?? null,
    bitrateKbps: out.mdat ? Math.round((out.mdat * 8) / out.duration / 1000) : null,
    chapters: out.chapters,
  };
}

/** @param {Uint8Array} b */
function wavChunks(b) {
  /** @type {{fmt?: {audioFormat: number, channels: number, sampleRate: number, byteRate: number, bits: number}, data?: {offset: number, size: number}}} */
  const out = {};
  let p = 12;
  while (p + 8 <= b.length) {
    const id = ascii(b, p, 4);
    const size = le32(b, p + 4);
    if (id === 'fmt ') {
      out.fmt = { audioFormat: le16(b, p + 8), channels: le16(b, p + 10), sampleRate: le32(b, p + 12), byteRate: le32(b, p + 16), bits: le16(b, p + 22) };
    } else if (id === 'data') {
      out.data = { offset: p + 8, size: Math.min(size, b.length - p - 8) };
    }
    p += 8 + size + (size & 1);
  }
  return out;
}

/** @param {Uint8Array} b */
export function probeWav(b) {
  const { fmt, data } = wavChunks(b);
  if (!fmt || !data) return { format: 'wav', error: 'missing fmt or data chunk' };
  return {
    format: 'wav',
    mime: 'audio/wav',
    duration: round(data.size / fmt.byteRate),
    sampleRate: fmt.sampleRate,
    channels: fmt.channels,
    bitDepth: fmt.bits,
    bitrateKbps: Math.round((fmt.byteRate * 8) / 1000),
    cbr: true,
  };
}

/**
 * Loudness of a 16-bit PCM WAV: overall RMS, sample peak, and the quietest
 * half-second window's RMS (a stand-in for the noise floor, measured on the
 * room tone at the head and tail of a chapter). All in dBFS.
 * @param {Uint8Array} b
 */
export function measureWavLoudness(b) {
  const { fmt, data } = wavChunks(b);
  if (!fmt || !data) return { error: 'missing fmt or data chunk' };
  if (fmt.audioFormat !== 1 || fmt.bits !== 16) return { error: 'loudness is measured on 16-bit PCM WAV only' };
  const view = new DataView(b.buffer, b.byteOffset + data.offset, data.size - (data.size % 2));
  const n = view.byteLength / 2;
  const win = Math.max(1, Math.floor((fmt.sampleRate * fmt.channels) / 2));
  let sum = 0, peak = 0, winSum = 0, winCount = 0, minWin = Infinity;
  for (let i = 0; i < n; i++) {
    const s = view.getInt16(i * 2, true) / 32768;
    const sq = s * s;
    sum += sq;
    winSum += sq;
    if (Math.abs(s) > peak) peak = Math.abs(s);
    if (++winCount === win) { minWin = Math.min(minWin, winSum / win); winSum = 0; winCount = 0; }
  }
  const db = (/** @type {number} */ x) => (x > 0 ? round(10 * Math.log10(x), 1) : -Infinity);
  return {
    rmsDb: db(sum / n),
    peakDb: peak > 0 ? round(20 * Math.log10(peak), 1) : -Infinity,
    noiseFloorDb: db(minWin === Infinity ? sum / n : minWin),
  };
}

/** @param {Uint8Array} b */
export function probePng(b) {
  const colorType = b[25];
  return {
    format: 'png', mime: 'image/png',
    width: u32(b, 16), height: u32(b, 20),
    colorModel: colorType === 0 || colorType === 4 ? 'grayscale' : 'rgb',
  };
}

/** @param {Uint8Array} b */
export function probeJpeg(b) {
  let p = 2;
  while (p + 9 < b.length) {
    if (b[p] !== 0xff) { p++; continue; }
    const marker = b[p + 1];
    if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) { p += 2; continue; }
    const len = u16(b, p + 2);
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      const components = b[p + 9];
      return {
        format: 'jpeg', mime: 'image/jpeg',
        height: u16(b, p + 5), width: u16(b, p + 7),
        colorModel: components === 1 ? 'grayscale' : components === 4 ? 'cmyk' : 'rgb',
        progressive: marker === 0xc2,
      };
    }
    p += 2 + len;
  }
  return { format: 'jpeg', error: 'no frame header found' };
}

/**
 * Probes any supported file. Always returns an object with `format`; on a file
 * it cannot read, also `error`.
 * @param {Uint8Array} b
 * @returns {Record<string, any>}
 */
export function probe(b) {
  const kind = sniff(b);
  const info = kind === 'mp3' ? probeMp3(b)
    : kind === 'mp4' ? probeMp4(b)
    : kind === 'wav' ? probeWav(b)
    : kind === 'png' ? probePng(b)
    : kind === 'jpeg' ? probeJpeg(b)
    : { format: 'unknown', error: 'not an MP3, M4A/M4B, WAV, PNG or JPEG file' };
  return { ...info, bytes: b.length };
}

/** @param {number} x @param {number} [digits] */
function round(x, digits = 3) {
  const f = 10 ** digits;
  return Math.round(x * f) / f;
}

/**
 * 3725.4 -> "01:02:05" (the itunes:duration form podcast apps all read).
 * @param {number} seconds
 */
export function hhmmss(seconds) {
  const s = Math.round(seconds);
  const pad = (/** @type {number} */ n) => String(n).padStart(2, '0');
  return `${pad(Math.floor(s / 3600))}:${pad(Math.floor((s % 3600) / 60))}:${pad(s % 60)}`;
}

podcast.mjs.text:
// @ts-check
// Builds a podcast RSS feed from a publish.json project: RSS 2.0 with the
// iTunes namespace Apple Podcasts and Spotify read, the Podcasting 2.0
// namespace (podcast:guid, podcast:locked, podcast:transcript), and
// atom:link rel="self". Also lists what a project is still missing, as
// findings an agent can act on one by one. Pure and browser-safe.

import { xml, cdata, rfc822, podcastGuid } from './util.mjs';
import { hhmmss } from './media.mjs';

/**
 * @typedef {{
 *   title: string, description?: string, file?: string, url?: string,
 *   bytes?: number, duration?: number, mime?: string, pubDate?: string,
 *   guid?: string, season?: number, episode?: number,
 *   episodeType?: 'full'|'trailer'|'bonus', explicit?: boolean, image?: string,
 *   transcript?: {url: string, type: string}, link?: string,
 * }} Episode
 * @typedef {{
 *   title: string, description: string, author?: string,
 *   owner?: {name?: string, email?: string}, language: string, link: string,
 *   feedUrl: string, baseUrl?: string, image: string, categories: string[],
 *   explicit?: boolean, type?: 'episodic'|'serial', copyright?: string,
 *   locked?: boolean, guid?: string, complete?: boolean,
 * }} Show
 * @typedef {{kind?: string, show: Show, episodes: Episode[]}} PodcastProject
 * @typedef {{severity: 'danger'|'notice', field: string, message: string, fix?: string}} Finding
 */

// Apple's documented category list: top level, and the subcategories under
// each. Used both to write <itunes:category> nesting and to flag a typo.
export const APPLE_CATEGORIES = {
  'Arts': ['Books', 'Design', 'Fashion & Beauty', 'Food', 'Performing Arts', 'Visual Arts'],
  'Business': ['Careers', 'Entrepreneurship', 'Investing', 'Management', 'Marketing', 'Non-Profit'],
  'Comedy': ['Comedy Interviews', 'Improv', 'Stand-Up'],
  'Education': ['Courses', 'How To', 'Language Learning', 'Self-Improvement'],
  'Fiction': ['Comedy Fiction', 'Drama', 'Science Fiction'],
  'Government': [],
  'History': [],
  'Health & Fitness': ['Alternative Health', 'Fitness', 'Medicine', 'Mental Health', 'Nutrition', 'Sexuality'],
  'Kids & Family': ['Education for Kids', 'Parenting', 'Pets & Animals', 'Stories for Kids'],
  'Leisure': ['Animation & Manga', 'Automotive', 'Aviation', 'Crafts', 'Games', 'Hobbies', 'Home & Garden', 'Video Games'],
  'Music': ['Music Commentary', 'Music History', 'Music Interviews'],
  'News': ['Business News', 'Daily News', 'Entertainment News', 'News Commentary', 'Politics', 'Sports News', 'Tech News'],
  'Religion & Spirituality': ['Buddhism', 'Christianity', 'Hinduism', 'Islam', 'Judaism', 'Religion', 'Spirituality'],
  'Science': ['Astronomy', 'Chemistry', 'Earth Sciences', 'Life Sciences', 'Mathematics', 'Natural Sciences', 'Nature', 'Physics', 'Social Sciences'],
  'Society & Culture': ['Documentary', 'Personal Journals', 'Philosophy', 'Places & Travel', 'Relationships'],
  'Sports': ['Baseball', 'Basketball', 'Cricket', 'Fantasy Sports', 'Football', 'Golf', 'Hockey', 'Rugby', 'Running', 'Soccer', 'Swimming', 'Tennis', 'Volleyball', 'Wilderness', 'Wrestling'],
  'Technology': [],
  'True Crime': [],
  'TV & Film': ['After Shows', 'Film History', 'Film Interviews', 'Film Reviews', 'TV Reviews'],
};

/** "Arts > Books" -> ["Arts", "Books"] @param {string} c */
export function splitCategory(c) {
  return String(c).split('>').map((s) => s.trim()).filter(Boolean);
}

/**
 * The enclosure URL for an episode: its own `url`, else the show's `baseUrl`
 * joined with the file's name.
 * @param {Show} show @param {Episode} ep
 */
export function enclosureUrl(show, ep) {
  if (ep.url) return ep.url;
  if (!ep.file || !show.baseUrl) return '';
  const name = ep.file.split(/[\\/]/).pop() ?? '';
  return show.baseUrl.replace(/\/?$/, '/') + encodeURIComponent(name);
}

/**
 * Everything the project still lacks before a feed built from it would be
 * accepted, most serious first. An empty list means "build it".
 * @param {PodcastProject} project
 * @returns {Finding[]}
 */
export function lintPodcast(project) {
  /** @type {Finding[]} */
  const out = [];
  const show = project.show ?? /** @type {Show} */ ({});
  /** @param {Finding['severity']} severity @param {string} field @param {string} message @param {string} [fix] */
  const add = (severity, field, message, fix) => out.push({ severity, field, message, ...(fix ? { fix } : {}) });

  for (const f of /** @type {const} */ (['title', 'description', 'language', 'link', 'feedUrl', 'image'])) {
    if (!show[f]) add('danger', `show.${f}`, `show.${f} is empty; Apple Podcasts requires it.`);
  }
  if (!show.owner?.email) add('notice', 'show.owner.email', 'No owner email. Apple and Spotify send ownership-verification mail to itunes:owner, and podcast:locked needs it.');
  if (show.feedUrl && !/^https:\/\//.test(show.feedUrl)) add('notice', 'show.feedUrl', 'feedUrl is not https. Apple Podcasts requires feeds and media served over HTTPS.');
  if (show.image && !/\.(jpe?g|png)(\?|$)/i.test(show.image)) add('notice', 'show.image', 'Cover art should be a .jpg or .png URL.');
  if (show.description && show.description.length > 4000) add('danger', 'show.description', `Description is ${show.description.length} characters; Apple's limit is 4000.`);
  const cats = show.categories ?? [];
  if (!cats.length) add('danger', 'show.categories', 'No category. Apple Podcasts requires at least one itunes:category.', 'e.g. "Technology" or "Arts > Books"');
  for (const c of cats) {
    const [top, sub] = splitCategory(c);
    const subs = APPLE_CATEGORIES[/** @type {keyof typeof APPLE_CATEGORIES} */ (top)];
    if (!subs) add('danger', 'show.categories', `"${top}" is not on Apple's top-level category list.`, `one of: ${Object.keys(APPLE_CATEGORIES).join(', ')}`);
    else if (sub && !subs.includes(sub)) add('danger', 'show.categories', `"${sub}" is not a subcategory of "${top}".`, subs.length ? `one of: ${subs.join(', ')}` : `"${top}" has no subcategories`);
  }
  if (show.explicit === undefined) add('notice', 'show.explicit', 'show.explicit is unset; it will be written as false.');

  const eps = project.episodes ?? [];
  if (!eps.length) add('danger', 'episodes', 'No episodes yet. Apple Podcasts will not accept a feed with none.', 'publish-kit podcast add <audio-file> --title "..."');
  const guids = new Map();
  eps.forEach((ep, i) => {
    const at = `episodes[${i}]`;
    if (!ep.title) add('danger', `${at}.title`, 'Episode has no title.');
    if (!enclosureUrl(show, ep)) add('danger', `${at}.url`, `"${ep.title || i}" has no audio URL.`, 'set episodes[].url, or show.baseUrl so the file name is appended to it');
    if (!ep.bytes) add('danger', `${at}.bytes`, `"${ep.title || i}" has no file size; the enclosure length must be the byte count.`, 'publish-kit podcast add reads it from the file');
    if (!ep.duration) add('notice', `${at}.duration`, `"${ep.title || i}" has no duration.`);
    if (!ep.pubDate) add('danger', `${at}.pubDate`, `"${ep.title || i}" has no publish date.`);
    else if (Number.isNaN(new Date(ep.pubDate).getTime())) add('danger', `${at}.pubDate`, `"${ep.pubDate}" is not a date.`);
    if (!ep.guid) add('danger', `${at}.guid`, `"${ep.title || i}" has no guid. Without a stable one, apps re-show or drop the episode when anything about it changes.`);
    else if (guids.has(ep.guid)) add('danger', `${at}.guid`, `guid "${ep.guid}" is also used by episodes[${guids.get(ep.guid)}].`);
    else guids.set(ep.guid, i);
    if (ep.episodeType && !['full', 'trailer', 'bonus'].includes(ep.episodeType)) add('danger', `${at}.episodeType`, `episodeType must be full, trailer or bonus, not "${ep.episodeType}".`);
    if (show.type === 'serial' && !ep.episode) add('notice', `${at}.episode`, 'Serial shows should number every episode so apps play them in order.');
  });
  return out.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'danger' ? -1 : 1));
}

/**
 * Renders the feed. Episodes are written newest first.
 * @param {PodcastProject} project
 * @param {{now?: Date, generator?: string}} [opts]
 */
export function buildPodcastFeed(project, opts = {}) {
  const show = project.show;
  const now = opts.now ?? new Date();
  const bool = (/** @type {boolean|undefined} */ v) => (v ? 'true' : 'false');
  const lines = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<rss version="2.0" xmlns:itunes="http://www.itunes.com/dtds/podcast-1.0.dtd" xmlns:podcast="https://podcastindex.org/namespace/1.0" xmlns:atom="http://www.w3.org/2005/Atom" xmlns:content="http://purl.org/rss/1.0/modules/content/">',
    '<channel>',
    `  <title>${xml(show.title)}</title>`,
    `  <link>${xml(show.link)}</link>`,
    `  <atom:link href="${xml(show.feedUrl)}" rel="self" type="application/rss+xml"/>`,
    `  <description>${cdata(show.description)}</description>`,
    `  <itunes:summary>${cdata(show.description)}</itunes:summary>`,
    `  <language>${xml(show.language)}</language>`,
    show.copyright ? `  <copyright>${xml(show.copyright)}</copyright>` : '',
    `  <lastBuildDate>${rfc822(now)}</lastBuildDate>`,
    `  <generator>${xml(opts.generator ?? 'publish-kit')}</generator>`,
    `  <podcast:guid>${xml(show.guid || (show.feedUrl ? podcastGuid(show.feedUrl) : ''))}</podcast:guid>`,
    show.owner?.email ? `  <podcast:locked owner="${xml(show.owner.email)}">${show.locked === false ? 'no' : 'yes'}</podcast:locked>` : '',
    show.author ? `  <itunes:author>${xml(show.author)}</itunes:author>` : '',
    show.owner ? `  <itunes:owner>${show.owner.name ? `<itunes:name>${xml(show.owner.name)}</itunes:name>` : ''}${show.owner.email ? `<itunes:email>${xml(show.owner.email)}</itunes:email>` : ''}</itunes:owner>` : '',
    `  <itunes:image href="${xml(show.image)}"/>`,
    `  <image><url>${xml(show.image)}</url><title>${xml(show.title)}</title><link>${xml(show.link)}</link></image>`,
    ...(show.categories ?? []).map((c) => {
      const [top, sub] = splitCategory(c);
      return sub
        ? `  <itunes:category text="${xml(top)}"><itunes:category text="${xml(sub)}"/></itunes:category>`
        : `  <itunes:category text="${xml(top)}"/>`;
    }),
    `  <itunes:explicit>${bool(show.explicit)}</itunes:explicit>`,
    `  <itunes:type>${show.type === 'serial' ? 'serial' : 'episodic'}</itunes:type>`,
    show.complete ? '  <itunes:complete>Yes</itunes:complete>' : '',
  ];
  const eps = [...(project.episodes ?? [])].sort((a, b) => new Date(b.pubDate ?? 0).getTime() - new Date(a.pubDate ?? 0).getTime());
  for (const ep of eps) {
    lines.push(
      '  <item>',
      `    <title>${xml(ep.title)}</title>`,
      ep.description ? `    <description>${cdata(ep.description)}</description>` : '',
      ep.description ? `    <content:encoded>${cdata(ep.description)}</content:encoded>` : '',
      ep.link ? `    <link>${xml(ep.link)}</link>` : '',
      `    <guid isPermaLink="false">${xml(ep.guid)}</guid>`,
      ep.pubDate ? `    <pubDate>${rfc822(ep.pubDate)}</pubDate>` : '',
      `    <enclosure url="${xml(enclosureUrl(show, ep))}" length="${ep.bytes ?? 0}" type="${xml(ep.mime || 'audio/mpeg')}"/>`,
      ep.duration ? `    <itunes:duration>${hhmmss(ep.duration)}</itunes:duration>` : '',
      ep.season ? `    <itunes:season>${ep.season}</itunes:season>` : '',
      ep.episode ? `    <itunes:episode>${ep.episode}</itunes:episode>` : '',
      `    <itunes:episodeType>${ep.episodeType || 'full'}</itunes:episodeType>`,
      `    <itunes:explicit>${bool(ep.explicit ?? show.explicit)}</itunes:explicit>`,
      ep.image ? `    <itunes:image href="${xml(ep.image)}"/>` : '',
      ep.transcript?.url ? `    <podcast:transcript url="${xml(ep.transcript.url)}" type="${xml(ep.transcript.type || 'text/vtt')}"/>` : '',
      '  </item>',
    );
  }
  lines.push('</channel>', '</rss>', '');
  return lines.filter((l) => l !== '').join('\n');
}

/**
 * A plain, indexable HTML page for the show: what search engines and people
 * without a podcast app see, linking the feed and every episode's audio.
 * @param {PodcastProject} project
 */
export function buildShowPage(project) {
  const show = project.show;
  const eps = [...(project.episodes ?? [])].sort((a, b) => new Date(b.pubDate ?? 0).getTime() - new Date(a.pubDate ?? 0).getTime());
  const ld = {
    '@context': 'https://schema.org', '@type': 'PodcastSeries', name: show.title, description: show.description,
    url: show.link, webFeed: show.feedUrl, image: show.image, inLanguage: show.language,
    ...(show.author ? { author: { '@type': 'Person', name: show.author } } : {}),
  };
  const items = eps.map((ep) => `<li><h2>${xml(ep.title)}</h2>${ep.pubDate ? `<p><time datetime="${xml(new Date(ep.pubDate).toISOString())}">${xml(new Date(ep.pubDate).toDateString())}</time>${ep.duration ? ` · ${hhmmss(ep.duration)}` : ''}</p>` : ''}<audio controls preload="none" src="${xml(enclosureUrl(show, ep))}"></audio>${ep.description ? `<div>${ep.description}</div>` : ''}</li>`).join('\n');
  return `<!doctype html>
<html lang="${xml(show.language)}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${xml(show.title)} (podcast)</title>
<meta name="description" content="${xml(String(show.description).replace(/<[^>]+>/g, '').slice(0, 155))}">
<link rel="alternate" type="application/rss+xml" title="${xml(show.title)}" href="${xml(show.feedUrl)}">
<meta property="og:title" content="${xml(show.title)}"><meta property="og:image" content="${xml(show.image)}"><meta property="og:type" content="website">
<script type="application/ld+json">${JSON.stringify(ld).replace(/</g, '\\u003c')}</script>
<style>body{font:16px/1.55 system-ui,sans-serif;max-width:720px;margin:auto;padding:24px}img{max-width:180px;border-radius:12px}ul{list-style:none;padding:0}li{border-top:1px solid #ddd;padding:12px 0}audio{width:100%}</style>
</head>
<body>
<header><img src="${xml(show.image)}" alt="${xml(show.title)} cover art"><h1>${xml(show.title)}</h1><p>${xml(String(show.description).replace(/<[^>]+>/g, ''))}</p>
<p><a href="${xml(show.feedUrl)}">RSS feed</a> — paste it into any podcast app to subscribe.</p></header>
<ul>
${items}
</ul>
</body>
</html>
`;
}

usage.mjs.text:
// @ts-check
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// show, the book, file names, or anything typed or dropped in -- that
// is exactly the kind of thing that must not be transmitted anywhere, and
// this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'publish-kit-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}

util.mjs.text:
// @ts-check
// Small shared helpers: XML escaping, RFC 822 dates, SHA-1 and UUIDv5 (for the
// Podcasting 2.0 podcast:guid), CRC-32 and slugs. Pure and browser-safe.

/** @param {unknown} s */
export function xml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

/** Text that may hold HTML (show notes) goes in CDATA, split if it contains "]]>". @param {string} s */
export function cdata(s) {
  return `<![CDATA[${String(s ?? '').split(']]>').join(']]]]><![CDATA[>')}]]>`;
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/**
 * RFC 822 date, the form RSS 2.0 requires for pubDate: "Wed, 02 Oct 2024 15:00:00 GMT".
 * @param {string|number|Date} when
 */
export function rfc822(when) {
  const d = when instanceof Date ? when : new Date(when);
  if (Number.isNaN(d.getTime())) throw new Error(`not a date: ${when}`);
  const p = (/** @type {number} */ n) => String(n).padStart(2, '0');
  return `${DAYS[d.getUTCDay()]}, ${p(d.getUTCDate())} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}:${p(d.getUTCSeconds())} GMT`;
}

/** @param {Uint8Array} msg @returns {Uint8Array} */
export function sha1(msg) {
  const ml = msg.length;
  const withPad = new Uint8Array(((ml + 9 + 63) >> 6) << 6);
  withPad.set(msg);
  withPad[ml] = 0x80;
  const dv = new DataView(withPad.buffer);
  dv.setUint32(withPad.length - 8, Math.floor((ml * 8) / 2 ** 32));
  dv.setUint32(withPad.length - 4, (ml * 8) >>> 0);
  let h0 = 0x67452301, h1 = 0xefcdab89, h2 = 0x98badcfe, h3 = 0x10325476, h4 = 0xc3d2e1f0;
  const w = new Uint32Array(80);
  for (let off = 0; off < withPad.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);
    for (let i = 16; i < 80; i++) { const x = w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]; w[i] = (x << 1) | (x >>> 31); }
    let a = h0, b = h1, c = h2, d = h3, e = h4;
    for (let i = 0; i < 80; i++) {
      const [f, k] = i < 20 ? [(b & c) | (~b & d), 0x5a827999]
        : i < 40 ? [b ^ c ^ d, 0x6ed9eba1]
        : i < 60 ? [(b & c) | (b & d) | (c & d), 0x8f1bbcdc]
        : [b ^ c ^ d, 0xca62c1d6];
      const t = (((a << 5) | (a >>> 27)) + f + e + k + w[i]) >>> 0;
      e = d; d = c; c = (b << 30) | (b >>> 2); b = a; a = t;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0; h4 = (h4 + e) >>> 0;
  }
  const out = new Uint8Array(20);
  const ov = new DataView(out.buffer);
  [h0, h1, h2, h3, h4].forEach((h, i) => ov.setUint32(i * 4, h));
  return out;
}

/**
 * RFC 4122 version-5 UUID of `name` in `namespace`.
 * @param {string} name @param {string} namespace
 */
export function uuidv5(name, namespace) {
  const ns = namespace.replace(/-/g, '').match(/../g)?.map((h) => parseInt(h, 16)) ?? [];
  const bytes = new TextEncoder().encode(name);
  const buf = new Uint8Array(16 + bytes.length);
  buf.set(ns, 0);
  buf.set(bytes, 16);
  const h = sha1(buf).slice(0, 16);
  h[6] = (h[6] & 0x0f) | 0x50;
  h[8] = (h[8] & 0x3f) | 0x80;
  const hex = [...h].map((x) => x.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

// The namespace the Podcasting 2.0 spec fixes for podcast:guid.
export const PODCAST_GUID_NAMESPACE = 'ead4c236-bf58-58c6-a2c6-a6b28d128cb6';

/**
 * The podcast:guid a feed URL should carry: UUIDv5 of the URL with its scheme
 * and trailing slashes removed, per the Podcasting 2.0 namespace.
 * @param {string} feedUrl
 */
export function podcastGuid(feedUrl) {
  return uuidv5(feedUrl.replace(/^[a-z]+:\/\//i, '').replace(/\/+$/, ''), PODCAST_GUID_NAMESPACE);
}

/** A random v4 UUID, from crypto.getRandomValues (browser and Node 18+). */
export function uuidv4() {
  const b = new Uint8Array(16);
  globalThis.crypto.getRandomValues(b);
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const hex = [...b].map((x) => x.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** @type {Uint32Array|undefined} */
let crcTable;
/** @param {Uint8Array} data */
export function crc32(data) {
  if (!crcTable) {
    crcTable = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c >>> 0;
    }
  }
  let c = 0xffffffff;
  for (let i = 0; i < data.length; i++) c = crcTable[(c ^ data[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

/** @param {string} s */
export function slugify(s) {
  return String(s).toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'item';
}

zip.mjs.text:
// @ts-check
// A minimal ZIP writer, enough for EPUB: entries in the order given, each
// either stored or deflated by a caller-supplied raw-deflate function (Node's
// zlib.deflateRawSync in the CLI; none in the browser, where entries are
// stored, which is valid ZIP and valid EPUB). Pure and browser-safe.

import { crc32 } from './util.mjs';

/**
 * @typedef {{name: string, data: Uint8Array|string, store?: boolean}} ZipEntry
 * @param {ZipEntry[]} entries
 * @param {{deflateRaw?: (data: Uint8Array) => Uint8Array, date?: Date}} [opts]
 * @returns {Uint8Array}
 */
export function buildZip(entries, opts = {}) {
  const enc = new TextEncoder();
  const d = opts.date ?? new Date(Date.UTC(2020, 0, 1));
  const dosTime = (d.getUTCHours() << 11) | (d.getUTCMinutes() << 5) | (d.getUTCSeconds() >> 1);
  const dosDate = ((d.getUTCFullYear() - 1980) << 9) | ((d.getUTCMonth() + 1) << 5) | d.getUTCDate();
  const chunks = /** @type {Uint8Array[]} */ ([]);
  const central = /** @type {Uint8Array[]} */ ([]);
  let offset = 0;
  for (const e of entries) {
    const name = enc.encode(e.name);
    const raw = typeof e.data === 'string' ? enc.encode(e.data) : e.data;
    const crc = crc32(raw);
    let body = raw, method = 0;
    if (!e.store && opts.deflateRaw) {
      const z = opts.deflateRaw(raw);
      if (z.length < raw.length) { body = z; method = 8; }
    }
    const local = new Uint8Array(30 + name.length);
    const lv = new DataView(local.buffer);
    lv.setUint32(0, 0x04034b50, true);
    lv.setUint16(4, 20, true);
    lv.setUint16(6, 0x0800, true); // UTF-8 names
    lv.setUint16(8, method, true);
    lv.setUint16(10, dosTime, true);
    lv.setUint16(12, dosDate, true);
    lv.setUint32(14, crc, true);
    lv.setUint32(18, body.length, true);
    lv.setUint32(22, raw.length, true);
    lv.setUint16(26, name.length, true);
    local.set(name, 30);
    const cen = new Uint8Array(46 + name.length);
    const cv = new DataView(cen.buffer);
    cv.setUint32(0, 0x02014b50, true);
    cv.setUint16(4, 20, true);
    cv.setUint16(6, 20, true);
    cv.setUint16(8, 0x0800, true);
    cv.setUint16(10, method, true);
    cv.setUint16(12, dosTime, true);
    cv.setUint16(14, dosDate, true);
    cv.setUint32(16, crc, true);
    cv.setUint32(20, body.length, true);
    cv.setUint32(24, raw.length, true);
    cv.setUint16(28, name.length, true);
    cv.setUint32(42, offset, true);
    cen.set(name, 46);
    chunks.push(local, body);
    central.push(cen);
    offset += local.length + body.length;
  }
  const cenSize = central.reduce((n, c) => n + c.length, 0);
  const end = new Uint8Array(22);
  const ev = new DataView(end.buffer);
  ev.setUint32(0, 0x06054b50, true);
  ev.setUint16(8, entries.length, true);
  ev.setUint16(10, entries.length, true);
  ev.setUint32(12, cenSize, true);
  ev.setUint32(16, offset, true);
  const all = [...chunks, ...central, end];
  const out = new Uint8Array(all.reduce((n, c) => n + c.length, 0));
  let p = 0;
  for (const c of all) { out.set(c, p); p += c.length; }
  return out;
}

/**
 * Lists a ZIP's entries from its central directory (for checks and tests).
 * @param {Uint8Array} b
 * @returns {{name: string, method: number, offset: number, compressedSize: number, size: number}[]}
 */
export function listZip(b) {
  const v = new DataView(b.buffer, b.byteOffset, b.byteLength);
  let eocd = -1;
  for (let i = b.length - 22; i >= Math.max(0, b.length - 65557); i--) {
    if (v.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) throw new Error('not a ZIP file (no end-of-central-directory record)');
  const count = v.getUint16(eocd + 10, true);
  let p = v.getUint32(eocd + 16, true);
  const dec = new TextDecoder();
  const out = [];
  for (let i = 0; i < count; i++) {
    const nameLen = v.getUint16(p + 28, true);
    out.push({
      name: dec.decode(b.subarray(p + 46, p + 46 + nameLen)),
      method: v.getUint16(p + 10, true),
      compressedSize: v.getUint32(p + 20, true),
      size: v.getUint32(p + 24, true),
      offset: v.getUint32(p + 42, true),
    });
    p += 46 + nameLen + v.getUint16(p + 30, true) + v.getUint16(p + 32, true);
  }
  return out;
}
